    /**
     * Method to retrieve the Attestation via AttestationFetchOneSummary
     * @param 	summary AttestationFetchOneSummary 
     * @return 	AttestationFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Attestation getAttestation( AttestationFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "AttestationFetchOneSummary arg cannot be null" );
    	
    	Attestation entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Attestation
        	// --------------------------------------
        	CompletableFuture<Attestation> futureEntity = queryGateway.query(new FindAttestationQuery( new LoadAttestationFilter( summary.getAttestationId() ) ), ResponseTypes.instanceOf(Attestation.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Attestation with id " + summary.getAttestationId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


