    /**
     * assign Control on Attestation
     * @param		command AssignControlToAttestationCommand	
     * @exception	ProcessingException
     */     
	public void assignControl( AssignControlToAttestationCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getAttestationId() );
		
		ControlService childDelegate 	= ControlService.getControlInstance();
		AttestationService parentDelegate = AttestationService.getAttestationInstance();			
		UUID childId = command.getAssignment().getControlId();
		Control child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get Control using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

